VRRP - HSRP.ejemplo:
# Configuración típica de Keepalived (VRRP en Linux)
vrrp_instance VI_1 {
  state MASTER
  interface eth0
  virtual_router_id 51
  priority 110
  virtual_ipaddress { 10.0.1.1/24 }
}

bind - listen - accept - connect.ejemplo:
// Flujo en servidor TCP (pseudocódigo C/POSIX)
int srv = socket(AF_INET, SOCK_STREAM, 0);
bind(srv, &addr, sizeof(addr));     // Asocia IP:puerto
listen(srv, 1024);                 // Cola de conexiones listas
int client_fd = accept(srv, ...);  // Nuevo fd por cliente
// Cliente: connect(cli, &srv_addr, sizeof(srv_addr));
